                <h1 id="operationsv1">Operations(v1)</h1>

    

                                <h2 id="operationsv1-POSTapi-v1-operations-walk-in">Walk-in guest.</h2>

<p>
</p>

<p>Creates or reuses a guest, creates a reservation for the selected room,
and immediately checks the guest in.</p>

<span id="example-requests-POSTapi-v1-operations-walk-in">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost:8000/api/v1/operations/walk-in" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"first_name\": \"John\",
    \"last_name\": \"Doe\",
    \"id_number\": \"ID123456\",
    \"phone_number\": \"0712345678\",
    \"email\": \"john@example.com\",
    \"country\": \"Kenya\",
    \"city\": \"Nairobi\",
    \"address\": \"123 Main Street\",
    \"room_id\": 5,
    \"check_in\": \"2026-09-13\",
    \"check_out\": \"2026-09-15\",
    \"number_of_guests\": 2,
    \"notes\": \"Walk-in guest.\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/operations/walk-in"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "first_name": "John",
    "last_name": "Doe",
    "id_number": "ID123456",
    "phone_number": "0712345678",
    "email": "john@example.com",
    "country": "Kenya",
    "city": "Nairobi",
    "address": "123 Main Street",
    "room_id": 5,
    "check_in": "2026-09-13",
    "check_out": "2026-09-15",
    "number_of_guests": 2,
    "notes": "Walk-in guest."
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

</span>

